WITH o AS (SELECT order_id, any_value(user_id) user_id, min(event_ts) ts, any_value(revenue_cents) rc FROM events WHERE event_name='purchase' GROUP BY order_id)
SELECT u.is_internal, count(*) n, sum(rc) rev, avg(rc)/100.0 aov FROM o JOIN users u USING(user_id)
WHERE ts >= TIMESTAMP '2025-02-01' AND ts < TIMESTAMP '2025-03-01' GROUP BY ROLLUP(u.is_internal);

