with p as (
  select distinct on (e.event_id) e.event_id, e.order_id, e.revenue_cents, e.event_ts
  from events e join users u using (user_id)
  where e.event_name = 'purchase' and not u.is_internal
  order by e.event_id, e.ingested_at
), feb as (
  select * from p where event_ts >= TIMESTAMP '2025-02-01' and event_ts < TIMESTAMP '2025-03-01'
)
select ((select sum(revenue_cents) from feb)
      - coalesce((select sum(r.refund_cents) from refunds r join feb using (order_id)), 0)) / 100.0 as net_revenue_usd

