WITH d AS (
  SELECT * FROM events QUALIFY row_number() OVER (PARTITION BY event_id ORDER BY ingested_at) = 1
), f AS (
  SELECT d.* FROM d JOIN users u USING (user_id)
  WHERE NOT u.is_internal AND event_ts >= '2025-02-01' AND event_ts < '2025-03-01'
), rev AS (
  SELECT sum(p.revenue_cents) - coalesce(sum(r.refund_cents), 0) AS net_cents
  FROM f p LEFT JOIN refunds r USING (order_id)
  WHERE p.event_name = 'purchase'
), mau AS (
  SELECT count(DISTINCT user_id) AS n FROM f
  WHERE event_name IN ('view_product', 'add_to_cart', 'checkout', 'purchase')
)
SELECT rev.net_cents, mau.n, rev.net_cents / 100.0 / mau.n AS arpu_usd FROM rev, mau;

